BEGIN;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM mcommerce_staging_control.environment WHERE project_id='jcgvunffeskkbgsbomgy') THEN RAISE EXCEPTION 'STAGING_REQUIRED'; END IF; END $$;
SELECT set_config('qa.entitlement.site',(SELECT id::text FROM public.sites WHERE owner_id='20261013-aaaa-4aaa-8aaa-000000000001'),true);
DO $$ DECLARE sid uuid:=current_setting('qa.entitlement.site')::uuid; r jsonb; n integer:=0;
BEGIN
 IF sid IS NULL THEN RAISE EXCEPTION 'QA_SITE_REQUIRED';END IF;
 IF has_function_privilege('authenticated','public.simple_reconcile_subscription_entitlement(uuid,text)','execute') OR has_function_privilege('anon','public.simple_reconcile_subscription_entitlement(uuid,text)','execute') THEN RAISE EXCEPTION 'PAYMENT_RPC_EXPOSED'; END IF;n:=n+1;
 UPDATE public.site_subscriptions SET provider='mercadopago',provider_subscription_id='QA_FINAL_ENTITLEMENT',provider_status='authorized',last_paid_at=NULL,next_due_at=now()+interval '1 month',grace_until=NULL WHERE site_id=sid;
 r:=public.simple_reconcile_subscription_entitlement(sid,'QA_FINAL_ENTITLEMENT');IF r->>'status'<>'pending' THEN RAISE EXCEPTION 'UNPAID_AUTHORIZED_ACTIVE';END IF;n:=n+1;
 UPDATE public.sites SET is_suspended=true WHERE id=sid;
 INSERT INTO public.subscription_payment_events(site_id,provider,provider_subscription_id,provider_payment_id,provider_status,amount,currency,paid_at) VALUES(sid,'mercadopago','QA_FINAL_ENTITLEMENT','910131','approved',25000,'ARS',now()-interval '1 day');
 r:=public.simple_reconcile_subscription_entitlement(sid,'QA_FINAL_ENTITLEMENT');IF r->>'status'<>'active' THEN RAISE EXCEPTION 'PAID_NOT_ACTIVE';END IF;n:=n+1;
 IF NOT (SELECT is_suspended FROM public.sites WHERE id=sid) THEN RAISE EXCEPTION 'MODERATION_OVERRIDDEN';END IF;n:=n+1;
 INSERT INTO public.subscription_payment_events(site_id,provider,provider_subscription_id,provider_payment_id,provider_status,amount,currency) VALUES(sid,'mercadopago','QA_FINAL_ENTITLEMENT','910131','refunded',25000,'ARS');
 r:=public.simple_reconcile_subscription_entitlement(sid,'QA_FINAL_ENTITLEMENT');IF r->>'status'<>'past_due' OR r->>'last_paid_at' IS NOT NULL THEN RAISE EXCEPTION 'REFUND_KEPT_ACCESS';END IF;n:=n+1;
 r:=public.simple_reconcile_subscription_entitlement(sid,'QA_FINAL_ENTITLEMENT');IF r->>'status'<>'past_due' THEN RAISE EXCEPTION 'REPLAY_RESURRECTED_REFUND';END IF;n:=n+1;
 INSERT INTO public.subscription_payment_events(site_id,provider,provider_subscription_id,provider_payment_id,provider_status,amount,currency,paid_at) VALUES(sid,'mercadopago','QA_FINAL_ENTITLEMENT','910132','approved',25000,'ARS',now());
 r:=public.simple_reconcile_subscription_entitlement(sid,'QA_FINAL_ENTITLEMENT');IF r->>'status'<>'active' THEN RAISE EXCEPTION 'NEW_RENEWAL_IGNORED';END IF;n:=n+1;
 r:=public.simple_reconcile_subscription_entitlement(sid,'QA_FINAL_ENTITLEMENT');IF r->>'status'<>'active' THEN RAISE EXCEPTION 'OLD_REFUND_REVOKED_NEW_RENEWAL';END IF;n:=n+1;
 UPDATE public.site_subscriptions SET next_due_at=now()-interval '1 day' WHERE site_id=sid;
 r:=public.simple_reconcile_subscription_entitlement(sid,'QA_FINAL_ENTITLEMENT');IF r->>'status'<>'past_due' THEN RAISE EXCEPTION 'EXPIRED_ACCESS_ACTIVE';END IF;n:=n+1;
 UPDATE public.site_subscriptions SET grace_until=now()+interval '1 day' WHERE site_id=sid;
 r:=public.simple_reconcile_subscription_entitlement(sid,'QA_FINAL_ENTITLEMENT');IF r->>'status'<>'active' THEN RAISE EXCEPTION 'CONFIGURED_GRACE_IGNORED';END IF;n:=n+1;
 UPDATE public.site_subscriptions SET provider_status='paused' WHERE site_id=sid;
 r:=public.simple_reconcile_subscription_entitlement(sid,'QA_FINAL_ENTITLEMENT');IF r->>'status'<>'past_due' THEN RAISE EXCEPTION 'PAUSED_ACTIVE';END IF;n:=n+1;
 UPDATE public.site_subscriptions SET provider_status='cancelled' WHERE site_id=sid;
 r:=public.simple_reconcile_subscription_entitlement(sid,'QA_FINAL_ENTITLEMENT');IF r->>'status'<>'cancelled' THEN RAISE EXCEPTION 'CANCELLED_ACTIVE';END IF;n:=n+1;
 BEGIN PERFORM public.simple_reconcile_subscription_entitlement(sid,'WRONG_SUBSCRIPTION');RAISE EXCEPTION 'BINDING_NOT_ENFORCED';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'SUBSCRIPTION_BINDING_MISMATCH' THEN RAISE;END IF;END;n:=n+1;
 IF (SELECT subscription_status FROM public.sites WHERE id=sid)<>(SELECT status FROM public.site_subscriptions WHERE site_id=sid) THEN RAISE EXCEPTION 'SUBSCRIPTION_SITE_INCONSISTENT';END IF;n:=n+1;
 IF n<>14 THEN RAISE EXCEPTION 'INCOMPLETE_ENTITLEMENT_TEST';END IF;
END $$;
ROLLBACK;
SELECT 14 AS entitlement_checks_passed,'test_data_rolled_back' AS outcome;
